public class AccountCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Account impl) {
        try {
            return AccountChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectAccount()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectAccount()));
        check("rejects the allows-overdraft bug", false, verdict(new OverdraftAccount()));
        check("rejects the allows-negative-amounts bug", false, verdict(new NegativeAmountAccount()));
        check("rejects the mutates-on-refusal bug", false, verdict(new LeakyAccount()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectAccount implements Account {
    private double balance = 100.0;

    public boolean withdraw(double amount) {
        if (amount <= 0 || amount > balance) return false;
        balance -= amount;
        return true;
    }

    public double balance() {
        return balance;
    }
}

class AlsoCorrectAccount implements Account {
    private double funds = 100.0;

    public boolean withdraw(double amount) {
        if (amount <= 0) return false;
        if (amount > funds) return false;
        funds = funds - amount;
        return true;
    }

    public double balance() {
        return funds;
    }
}

class OverdraftAccount implements Account {
    private double balance = 100.0;

    public boolean withdraw(double amount) {
        if (amount <= 0) return false;
        balance -= amount;
        return true;
    }

    public double balance() {
        return balance;
    }
}

class NegativeAmountAccount implements Account {
    private double balance = 100.0;

    public boolean withdraw(double amount) {
        if (amount > balance) return false;
        balance -= amount;
        return true;
    }

    public double balance() {
        return balance;
    }
}

class LeakyAccount implements Account {
    private double balance = 100.0;

    public boolean withdraw(double amount) {
        if (amount <= 0) return false;
        balance -= amount;
        if (balance < 0) return false;
        return true;
    }

    public double balance() {
        return balance;
    }
}

