/**
 * TASK: Write the checks that decide whether an Account is correct.
 *
 * The Account contract. Every account handed to isCorrect is FRESH and starts
 * with a balance of exactly 100.0.
 *   withdraw(amount) returns true, and reduces the balance by amount, when
 *       amount > 0 AND amount <= the current balance (taking the whole balance
 *       is allowed).
 *   Otherwise withdraw returns false and leaves the balance COMPLETELY
 *       UNCHANGED -- no overdraft, no zero or negative withdrawals, no partial
 *       damage on the way out.
 *   balance() reports the current balance and never changes anything.
 *
 * This one cannot be checked with a single call. You have to drive a SEQUENCE
 * of calls on the one account you are given and inspect balance() AFTER each
 * step -- especially after a withdrawal that was refused, because one broken
 * account returns false and takes the money anyway.
 *
 * Wrap your calls in try/catch and return false if the implementation throws.
 */
interface Account {
    /* Provided -- do not edit. */
    boolean withdraw(double amount);

    double balance();
}

public class AccountChecker {

    public static boolean isCorrect(Account impl) {
        try {
            if (!close(impl.balance(), 100.0)) return false;

            // A refused withdrawal must not move any money.
            if (impl.withdraw(200.0)) return false;
            if (!close(impl.balance(), 100.0)) return false;

            if (impl.withdraw(-50.0)) return false;
            if (!close(impl.balance(), 100.0)) return false;

            if (impl.withdraw(0.0)) return false;
            if (!close(impl.balance(), 100.0)) return false;

            // A legal withdrawal moves exactly the requested amount.
            if (!impl.withdraw(30.0)) return false;
            if (!close(impl.balance(), 70.0)) return false;

            // Taking the whole remaining balance is allowed.
            if (!impl.withdraw(70.0)) return false;
            if (!close(impl.balance(), 0.0)) return false;

            if (impl.withdraw(1.0)) return false;
            if (!close(impl.balance(), 0.0)) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }

    private static boolean close(double actual, double expected) {
        return Math.abs(actual - expected) < 0.000001;
    }
}
